message.content:
{
  "candidate_edge_types": [
    {
      "name": "COMPLETION_CONFIRMATION_TRIGGERS_RECHECK",
      "definition": "A confirmation prompt returned in response to a task-completion request causes the agent to reopen its analysis and perform additional validation actions for requirements it may have overlooked before finalizing.",
      "source_description": "An observation that asks the agent to confirm a prior task-completion request before final grading.",
      "target_description": "A subsequent agent action that re-examines assumptions or inspects a previously unchecked requirement."
    },
    {
      "name": "REMEDIATES_IDENTIFIED_MISSING_PREREQUISITE",
      "definition": "An observation revealing that a required component or prerequisite is absent leads to a subsequent agent action that provisions or configures that missing component.",
      "source_description": "An observation showing that a required component or prerequisite is not present.",
      "target_description": "A subsequent agent action that installs or configures the missing component."
    },
    {
      "name": "VERIFIES_PERSISTENCE_OF_PRIOR_CONFIGURATION",
      "definition": "After earlier configuration work, the agent performs a check to confirm that a previously configured component is still functioning before continuing with new changes.",
      "source_description": "An earlier agent action that configured a component of the system.",
      "target_description": "A later check that confirms the previously configured component remains operational."
    },
    {
      "name": "CONTINUES_SETUP_AFTER_PARTIAL_ACTION_OUTCOME",
      "definition": "An observation indicating that a prior action only partially achieved its intended state leads the agent to perform a follow-up action that completes the remaining configuration.",
      "source_description": "An observation showing that a prior action left the system in an incomplete or not-yet-active state.",
      "target_description": "A subsequent agent action that completes the remaining part of the intended configuration."
    },
    {
      "name": "VERIFIES_ACTION_EFFECT_ON_SYSTEM_STATE",
      "definition": "After taking an action intended to change system state, the agent performs an inspection to confirm that the intended change actually took effect.",
      "source_description": "A prior agent action intended to modify the state of the system.",
      "target_description": "A subsequent inspection that confirms the expected state change is present."
    }
  ]
}

